insert into public.permission_catalog(key,domain,name,description,module,action,scopes,dependencies) values('backoffice.functions.cockpit_entity_query','tenant','Relatie- en personeelsbronvenster openen','Brongetrouw detail met de huidige oorspronkelijke dossier-, document- en werkbonrechten.','access','read',array['tenant'],array['backoffice.access']) on conflict(key) do nothing;
insert into private.management_role_permissions(tenant_id,role_id,capability) select r.tenant_id,r.id,'backoffice.functions.cockpit_entity_query' from private.management_roles r where r.code='owner' or exists(select 1 from private.management_role_permissions p where p.role_id=r.id and p.capability=any(array['backoffice.customers.read','backoffice.objects.read','backoffice.personnel.read'])) on conflict do nothing;
insert into public.permission_catalog(key,domain,name,description,module,action,scopes,dependencies) values('backoffice.functions.cockpit_customer_cards','tenant','Brongetrouwe klantenlijst lezen','De bestaande klantenlijst en RLS-contactgegevens in de Sites-presentatie.','customers','read',array['tenant'],array['backoffice.access','backoffice.customers.read','backoffice.functions.customer_list','backoffice.functions.cockpit_entity_query']) on conflict(key) do nothing;
insert into private.management_role_permissions(tenant_id,role_id,capability) select r.tenant_id,r.id,'backoffice.functions.cockpit_customer_cards' from private.management_roles r where r.code='owner' or exists(select 1 from private.management_role_permissions p where p.role_id=r.id and p.capability='backoffice.customers.read') on conflict do nothing;
